  function oct(name, size, cls, label) {
    var s = String(size || 16);
    var node = (ICONS[name] || {})[s] || (ICONS[name] || {})["16"];
    if (!node) return "";
    var a11y = label
      ? 'role="img" aria-label="' + String(label).replace(/"/g, "&quot;") + '"'
      : 'aria-hidden="true" focusable="false"';
    return '<svg class="octicon octicon-' + name + (cls ? " " + cls : "") +
      '" viewBox="0 0 ' + node.w + " 16" + '" width="' + s + '" height="' + s +
      '" fill="currentColor" display="inline-block" overflow="visible" ' + a11y + ">" +
      '<path d="' + node.p + '"/></svg>';
  }
  global.OCT = ICONS;
  global.oct = oct;
